package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 标签核销历史查询结果。时间窗 [from, to) 左闭右开（UTC）：from/to 为 null 表示该侧不限；
 * elapsedSeconds 为时间窗时长（to-from，两侧均给出时的实际秒数，否则为 null）；
