    @Test
    void concurrentSameLabelAcrossBatches_onlyOneSucceeds() throws Exception {
        String a = "BK-PK-CA-" + unique();
        String b = "BK-PK-CB-" + unique();
        preparePendingBatch(a);
        preparePendingBatch(b);
        registerPlan(a, "CK-PA", 10, 1000L, 1009L, 201);
        registerPlan(b, "CK-PB", 10, 1000L, 1009L, 201);

        List<Future<Integer>> results = runConcurrent(
                () -> callStatus(packRequest(a, "w", "CK-PACK-A", List.of(item(2000L, 1)))),
                () -> callStatus(packRequest(b, "w", "CK-PACK-B", List.of(item(2000L, 1))))
        );
        int ok = 0;
        int conflict = 0;
        for (Future<Integer> f : results) {
            int code = f.get(30, TimeUnit.SECONDS);
            if (code == 201) {
                ok++;
            } else if (code == 409) {
                conflict++;
            } else {
                fail("意外状态码: " + code);
            }
        }
        assertEquals(1, ok, "唯一约束保证同标签最多一次成功");
        assertEquals(1, conflict);
        assertEquals(Integer.valueOf(1), jdbc.queryForObject(
                "SELECT COUNT(*) FROM label_occupancy WHERE label_no = 2000", Integer.class));
        assertEquals(Integer.valueOf(1), jdbc.queryForObject(
                "SELECT COUNT(*) FROM packing_record WHERE label_no = 2000 AND status = 'ACTIVE'",
                Integer.class));
    }

