    // 同标签重新封满
    pack(batchKey, "w", "CK-PACK-2",
            List.of(item(1000L, 4), item(1001L, 6)), 201);

    approve(batchKey, "qa", "QUALITY", "CK-AP-1", 201);
    approve(batchKey, "ops", "OPERATIONS", "CK-AP-2", 201);

    JsonNode snapshot = detail(batchKey).path("snapshot");
